-- ========================================================

function UI_SuspendPanel:__init()
    self.controller = nil
    self.co_1 = nil
end


function UI_SuspendPanel:__delete()
    self.co_1 = nil
end



function UI_SuspendPanel:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end


function UI_SuspendPanel:Start()
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ==============================

    assert( self.suspendRTF and self.pauseButton )
    assert( self.infoButton and self.reGameButton and self.leaveButton )

    -- assert( self.piecesCollectionBH )
    -- self.piecesCollection = DreamSpaceLuaUtils.GetLuaScr(self.piecesCollectionBH.gameObject, "Game.DreamSpace.PiecesCollection.PiecesCollection" )
    -- assert( self.piecesCollection )

    self.pauseAnimation = KTool.GetComponent( self.pauseButton.gameObject, typeof(Animation) )
    assert( self.pauseAnimation )

    self.infoAnimator      = KTool.GetComponent( self.infoButton.gameObject, typeof(Animator) )
    self.reGameAnimator    = KTool.GetComponent( self.reGameButton.gameObject, typeof(Animator) )
    self.leaveAnimator     = KTool.GetComponent( self.leaveButton.gameObject, typeof(Animator) )
    assert( self.infoAnimator and self.reGameAnimator and self.leaveAnimator )

    -- pc端禁止 点击 右上角 暂定按钮
    if DreamSpaceStates.isWindowsPlatform == false then 
        self.pauseButton.onClick:AddListener( Bind(self, self.OnPressPauseButton) )
    end

    self.infoButton.onClick:AddListener( Bind(self, self.OnPressInfoButton) )
    self.reGameButton.onClick:AddListener( Bind(self, self.OnPressReGameButton) )
    self.leaveButton.onClick:AddListener( Bind(self, self.OnPressLeaveButton) )


    KTool.SetActive( self.suspendRTF.gameObject, false )
    
    
    self.pauseAnimation:Play( ButtonIdle )
end




function UI_SuspendPanel:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function UI_SuspendPanel:Update()


    if DreamSpaceStates.isWindowsPlatform == true and Input.GetKeyUp(KeyCode.Escape) then 

        print("koko - 按下 ESC - " .. DreamSpaceStates.SubPanelFreeInPC_ToString() .. "\n" .. DreamSpaceStates.InputLock_ToString() )
        if DreamSpaceStates.IsSubPanelFreeInPC() == true then 

            if DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.None then

                print("koko - 打开 SuspendPanel")
                -- 开:
                self:OnPressPauseButton() 
                -- 解除 鼠标锚点锁定:  (允许玩家点击 SuspendPanel 中其它按钮)
                Cursor.lockState = CursorLockMode.None
                DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
                DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.SuspendPanel    

            elseif DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.SuspendPanel then
                -- pc版中, 暂停面板开启后, 允许玩家按任意键退出
                self:OnPressReGameButton()
            end

        end
    end 
end 


function UI_SuspendPanel:OnPressPauseButton()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(function()
        self:_DoPauseButton()
    end)
end


function UI_SuspendPanel:_DoPauseButton()

    while self.pauseAnimation.isPlaying == true do
        coroutine.yield(Yielders.EndOfFrame)
    end

    -- if DreamSpaceStates.isWindowsPlatform == false then 
    --     self.pauseAnimation:Play( ButtonPressed )
    --     while self.pauseAnimation.isPlaying == true do
    --         coroutine.yield(Yielders.EndOfFrame)
    --     end
    -- end

    -- 弹出新界面:
    --self.mainCanvas.enabled = false

    -- 关闭 主UI 界面:
    local uiMain_OnOff = UIMain_OnOff.Instance()
    if isNotNull(uiMain_OnOff) then 
        uiMain_OnOff:Hide()
    end 

    KTool.SetActive( self.suspendRTF.gameObject, true )
end




function UI_SuspendPanel:OnPressInfoButton()
    print( "koko 按下 info 按钮")

    --  测试用临时 出口:
end


function UI_SuspendPanel:OnPressReGameButton()
    print( "koko 按下 返回游戏 按钮");

    if DreamSpaceStates.isWindowsPlatform == true then 
        if DreamSpaceStates.IsSubPanelFreeInPC() == true  and DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.SuspendPanel then 
            -- 关:
            -- 锁定 鼠标锚点:   (毕竟要回到游戏了...)
            Cursor.lockState = CursorLockMode.Locked
            DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
            
            DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.None               
        end
    end

    --self.mainCanvas.enabled = true

    -- 开启 主UI 界面:
    local uiMain_OnOff = UIMain_OnOff.Instance()
    if isNotNull(uiMain_OnOff) then 
        uiMain_OnOff:Show()
    end 

    KTool.SetActive( self.suspendRTF.gameObject, false )
end

  
function UI_SuspendPanel:OnPressLeaveButton()

    print( "koko 按下 中途离开 按钮")

    -- 解除 鼠标锚点锁定:  (要回到 主游戏 界面了)
    Cursor.lockState = CursorLockMode.None

    DreamSpaceStates.IsSubPanelFreeInPC_Reset() -- PC 版 禁止打开 ui 子界面 

    DreamSpaceSounds.Stop( DreamSpaceSounds.music.dream )


    -- 恢复暂帧率:
    if type(DreamSpaceStates.cachedFrameRate) == "number" and DreamSpaceStates.cachedFrameRate >= 30 then 
        Application.targetFrameRate = DreamSpaceStates.cachedFrameRate
    else
        printError("koko 暂存的白塔外部帧率丢失 " .. tostring(DreamSpaceStates.cachedFrameRate) )
        Application.targetFrameRate = 30
    end


    -- 本次游戏完成了几个 task: 
    local taskNum = checkInt( DreamSpaceStates.FinshedTaskNum )
    print("koko - 中途退出, 本次白塔 完成 " .. tostring(taskNum) .. " 个 task;" )

    local DreamlandComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DreamlandComponent)

    if checkNumber(DreamSpaceStates.questId) == 0 then 
        printError("koko 异常, questId 异常 = " .. tostring(DreamSpaceStates.questId) )
        return
    end 

    -- 设置 loading 界面的 bg图:
    local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
    KCookie.Set(Constants.UICacheDataKeys.OP_LOADING_IMG_ID, DreamSpaceStates.LoadingPanel_IMG_ID) 

    DreamlandComponent:OverseaBoxQuestGradeReq(
        {
            questId = DreamSpaceStates.questId,
            piece = {},             -- 不传碎片信息
            isPassed = 0,           -- 中途退出
            taskNum = taskNum
        },
        -- collectionIds 是将 piecesDatas 序列化为一个 string;
        function(rewards, collectionIds)   
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, { { id = Constants.UITypeIds.UIHomeView } }, Constants.LoadingType.Others, false)
        end
    )

end


return UI_SuspendPanel

